+1|// Stock portfolio visualization
+2|// Inputs: data/stock-descriptions.csv (one row per stock), data/indiv-stock/*.csv (price history)
+3|// Outputs: /root/output/index.html with a bubble chart (left) and a table (right)
+4|// D3 version: v6 (local, loaded from js/d3.v6.min.js)
 5|
+6|const SECTORS = ["Information Technology", "Industry", "Energy", "Financial", "ETF"];
+7|const SECTOR_COLORS = {
+8|    "Information Technology": "#4e79a7",
+9|    "Industry": "#f28e2b",
+10|    "Energy": "#59a14f",
+11|    "Financial": "#e15759",
+12|    "ETF": "#9c755f"
+13|};
+14|const ETF_RADIUS = 22;
+15|
+16|function formatMarketCap(v) {
+17|    if (v == null || isNaN(v) || v === "") return "";
+18|    const n = +v;
+19|    if (n >= 1e12) return (n / 1e12).toFixed(2) + "T";
+20|    if (n >= 1e9)  return (n / 1e9).toFixed(2)  + "B";
+21|    if (n >= 1e6)  return (n / 1e6).toFixed(2)  + "M";
+22|    return d3.format(",")(n);
+23|}
+24|
+25|d3.csv("data/stock-descriptions.csv").then(raw => {
+26|    const stocks = raw.map(d => ({
+27|        ticker: d.ticker,
+28|        name: d["full name"],
+29|        sector: d.sector,
+30|        marketCap: d.marketCap ? +d.marketCap : null,
+31|        country: d.country || "",
+32|        website: d.website || ""
+33|    }));
+34|
+35|    const svgEl = document.getElementById("bubble-svg");
+36|    const width = svgEl.clientWidth;
+37|    const height = svgEl.clientHeight;
+38|
+39|    const marketCaps = stocks.filter(s => s.marketCap).map(s => s.marketCap);
+40|    // sqrt scale -> area proportional to market cap
+41|    const radiusScale = d3.scaleSqrt()
+42|        .domain([d3.min(marketCaps), d3.max(marketCaps)])
+43|        .range([14, 55]);
+44|
+45|    stocks.forEach(s => {
+46|        s.radius = s.sector === "ETF" ? ETF_RADIUS : radiusScale(s.marketCap);
+47|    });
+48|
+49|    // Sector cluster centers arranged in a tight 3x2 grid centered in the chart
+50|    const presentSectors = SECTORS.filter(sec => stocks.some(s => s.sector === sec));
+51|    const cols = Math.min(3, presentSectors.length);
+52|    const rows = Math.ceil(presentSectors.length / cols);
+53|    const padX = width * 0.18;
+54|    const padY = height * 0.18;
+55|    const innerW = width - 2 * padX;
+56|    const innerH = height - 2 * padY;
+57|    const stepX = cols > 1 ? innerW / (cols - 1) : 0;
+58|    const stepY = rows > 1 ? innerH / (rows - 1) : 0;
+59|    const sectorCenters = {};
+60|    presentSectors.forEach((sec, i) => {
+61|        const col = i % cols;
+62|        const row = Math.floor(i / cols);
+63|        sectorCenters[sec] = {
+64|            x: padX + col * stepX,
+65|            y: padY + row * stepY
+66|        };
+67|    });
+68|
+69|    const svg = d3.select("#bubble-svg");
+70|    const chartG = svg.append("g").attr("class", "chart");
+71|    const legendG = svg.append("g").attr("class", "legend");
+72|
+73|    // Legend (top-left)
+74|    const legendItems = legendG.selectAll("g")
+75|        .data(presentSectors)
+76|        .join("g")
+77|        .attr("transform", (_, i) => `translate(10, ${12 + i * 20})`);
+78|    legendItems.append("rect")
+79|        .attr("width", 14).attr("height", 14)
+80|        .attr("rx", 2)
+81|        .attr("fill", d => SECTOR_COLORS[d]);
+82|    legendItems.append("text")
+83|        .attr("x", 20).attr("y", 11)
+84|        .text(d => d);
+85|
+86|    // Bubbles
+87|    const bubbleG = chartG.selectAll("g.node")
+88|        .data(stocks, d => d.ticker)
+89|        .join("g")
+90|        .attr("class", "node")
